     7	/**
     8	 * Main procedure for standalone fuzzing engine.
     9	 *
    10	 * Reads filenames from the argument array. For each filename, read the file
    11	 * into memory and then call the fuzzing interface with the data.
    12	 */
    13	int main(int argc, char **argv)
    14	{
    15	  LLVMFuzzerInitialize(&argc, &argv);
    16	
    17	  int ii;
    18	  for (ii = 1; ii < argc; ii++) {
    19	    FILE *infile;
    20	    printf("[%s] ", argv[ii]);
    21	
    22	    /* Try and open the file. */
    23	    infile = fopen(argv[ii], "rb");
    24	    if (infile) {
    25	      uint8_t *buffer = NULL;
    26	      size_t buffer_len;
    27	
    28	      printf("Opened.. ");
    29	
    30	      /* Get the length of the file. */
    31	      fseek(infile, 0L, SEEK_END);
    32	      buffer_len = ftell(infile);
    33	
    34	      /* Reset the file indicator to the beginning of the file. */
    35	      fseek(infile, 0L, SEEK_SET);
    36	
    37	      /* Allocate a buffer for the file contents. */
    38	      buffer = (uint8_t *)calloc(buffer_len, sizeof(uint8_t));
    39	      if (buffer) {
    40	        /* Read all the text from the file into the buffer. */
    41	        fread(buffer, sizeof(uint8_t), buffer_len, infile);
    42	        printf("Read %zu bytes, fuzzing.. ", buffer_len);
    43	
    44	        /* Call the fuzzer with the data. */
    45	        LLVMFuzzerTestOneInput(buffer, buffer_len);
    46	
    47	        printf("complete !!");
    48	
    49	        /* Free the buffer as it's no longer needed. */
    50	        free(buffer);
    51	        buffer = NULL;
    52	      } else {
    53	        fprintf(stderr,
    54	                "[%s] Failed to allocate %zu bytes \n",
    55	                argv[ii],
    56	                buffer_len);
    57	      }
    58	
    59	      /* Close the file as it's no longer needed. */
    60	      fclose(infile);
    61	      infile = NULL;
    62	    } else {
    63	      /* Failed to open the file. Maybe wrong name or wrong permissions? */
    64	      fprintf(stderr, "[%s] Open failed. \n", argv[ii]);
    65	    }
    66	
    67	    printf("\n");
    68	  }
